Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -52,9 +52,8 @@
 function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1800)}
 document.querySelectorAll('.hotspot').forEach(b=>b.onclick=()=>{const k=b.dataset.site,d=clues[k];document.getElementById('ptitle').textContent=d[0];document.getElementById('ptext').textContent=d[1];document.getElementById('psigil').textContent=d[2];document.getElementById('pname').textContent=d[3];document.getElementById('pdesc').textContent=d[4];const take=document.getElementById('take');take.disabled=found.includes(k);take.textContent=found.includes(k)?'In your journal':'Add to journal';take.onclick=()=>{if(found.includes(k))return;found.push(k);take.disabled=true;take.textContent='In your journal';update();toast(d[3]+' recorded');};document.getElementById('evidencePanel').classList.add('open')});
 document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('.panel').classList.remove('open'));
 function update(){document.getElementById('count').textContent=found.length+'/5';found.forEach((k,i)=>{const s=document.querySelectorAll('.slot')[i];s.classList.add('filled');s.textContent=clues[k][2];s.title=clues[k][3]})}
-document.getElementBy('deduce')
 document.getElementById('deduce').onclick=()=>{document.getElementById('deduction').classList.add('open')};
 document.querySelectorAll('.suspect').forEach(s=>s.onclick=()=>{document.querySelectorAll('.suspect').forEach(x=>x.classList.remove('selected'));s.classList.add('selected');selected=s.dataset.name});
 document.querySelector('.solve').onclick=()=>{if(found.length<5){toast('You still need '+(5-found.length)+' clue'+(5-found.length===1?'':'s'));return}if(!selected){toast('Select a suspect');return}const end=document.getElementById('end');document.getElementById('endtitle').textContent=selected==='Architect Senen'?'MYSTERY SOLVED':'THE TRAITOR ESCAPED';document.getElementById('endtext').textContent=selected==='Architect Senen'?'Senen’s secret passage, the copied map, and the newly cut floor prove he broke the royal seal. The tomb is sealed once more—and history is preserved.':selected+' confessed after your accusation—but the evidence points elsewhere. Senen vanished through the east passage as the curse closed behind him.';end.style.display='grid'};
 </script></body></html>
